import java.util.*;

class Solution {
  public List<String> generatePalindromes(String s) {
    int[] count = new int[128];
    for (char c : s.toCharArray()) count[c]++;
    String mid = "";
    for (int c = 0; c < 128; c++) {
      if (count[c] % 2 == 1) {
        if (!mid.isEmpty()) return new ArrayList<>();
        mid = String.valueOf((char) c);
      }
      count[c] /= 2; // half of each letter goes on the left side
    }
    List<String> ans = new ArrayList<>();
    build(count, new StringBuilder(), s.length() / 2, mid, ans);
    return ans;
  }

  private void build(int[] half, StringBuilder left, int len, String mid, List<String> ans) {
    if (left.length() == len) {
      ans.add(left + mid + new StringBuilder(left).reverse());
      return;
    }
    for (int c = 0; c < 128; c++) {
      if (half[c] == 0) continue;
      half[c]--;
      left.append((char) c);
      build(half, left, len, mid, ans);
      left.setLength(left.length() - 1);
      half[c]++;
    }
  }
}
